function roadmap(){
 const academic=AcademicPathway.plan(state,mode),completed=E.completedCodes(state.courses,state.profile?.target),planned=state.courses.filter(c=>!c.completed),limit={Balanced:15,Accelerated:20,Flexible:10}[mode];
 let generated=productBuildPlan();

 window.currentPlan=generated.courses;const terms=generated.courses.length?Math.max(...generated.courses.map(c=>c.term))+1:0,earned=state.creditSummary?.total??state.courses.filter(E.passing).reduce((n,c)=>n+c.credits,0),linked=state.courses.reduce((n,c)=>n+(c.creditOrigins?.length||0),0)+(state.creditLedger?.length||0);
 const completedCards=state.courses.filter(E.passing).map(c=>`<div class="completed-row"><div><strong>${esc(c.code)}</strong><span>${esc(c.title)}</span><small>${esc(c.institution)}${c.creditOrigins?.length?' · includes '+c.creditOrigins.map(o=>esc(o.code)+' at '+esc(o.institution)).join(', '):''}</small></div><span>${c.credits} cr</span></div>`).join('');
 return page('YOUR PLAN / BOTH SCHOOLS, ONE PATH','Your coursework. Your next classes.',`${progressPanel(generated)}<div class="plan-summary"><div><span class="tag">YOUR DESTINATION</span><h2>${esc(state.profile?.major||'Choose your major')}</h2><p>${esc(state.profile?.target||'Choose your university')}</p></div><div><strong>${earned}</strong><span>Credits counted once</span></div><div><strong>${terms||'—'}</strong><span>${academic.supported?'Core roadmap terms':'Draft terms'}</span></div></div>
 <div class="dual-enrollment-panel"><div><span class="tag">DUAL ENROLLMENT SUPPORTED</span><h3>UWB and community college can be part of the same plan.</h3><p>Your home school never removes Bellevue from your options. Verified alternatives can be mixed in one quarter; credit limits apply across both schools.</p></div><label><input type="checkbox" id="prefer-community" ${state.profile?.preferCommunity?'checked':''}> Prefer Bellevue for verified equivalents</label></div>
 <div class="plan-switch">${[['Accelerated','Most efficient',20],['Balanced','Balanced',15],['Flexible','More breathing room',10]].map(([id,label,credits])=>`<button class="${mode===id?'selected':''}" data-mode="${id}"><strong>${label}</strong><span>Up to ${credits} credits across all schools</span></button>`).join('')}</div>
 ${plannerLab(generated)}<div class="plan-status"><span>✓ ${linked} matching or overlapping transfer record(s) reconciled · Credit counted once</span><span>${esc(generated.method||'Draft schedule')}</span></div>
 <details class="completed-courses" open><summary>Your completed classes (${state.courses.filter(E.passing).length})</summary>${completedCards||'<p class="muted">No confirmed classes saved. Return to academic history to confirm the import.</p>'}${state.creditSummary?.coverage?.map(c=>`<p class="credit-reconciliation">${esc(c.institution)}: ${c.sourceCredits} source-college credits and ${c.transferCredits} awarded transfer credits overlap in ${c.range.join('–')}. ${c.uncovered?`${c.uncovered} additional transfer credits remain in your total.`:'Transfer copies are not added again.'}</p>`).join('')||''}<a class="text-link" href="#history">Review course and transfer evidence ↗</a></details>
 ${academic.readiness?`<div class="note">${esc(academic.readiness)}</div>`:''}${academic.warnings?.length?`<div class="note">${academic.warnings.map(esc).join('<br>')}</div>`:''}${generated.blocked.length?`<div class="note" role="alert">Not placed: ${generated.blocked.map(esc).join(', ')}. A prerequisite, minimum grade, course pairing, seasonal restriction, or workload limit needs review.</div>`:''}
 <div class="plan-main"><div><div class="row"><h2>${academic.supported?'Remaining foundation and core courses':'Your term-by-term route'}</h2><a class="text-link" href="#profile">Edit your goals ↗</a></div>
 ${academic.supported?`<p class="plan-scope">Generated automatically from UWB’s published EE curriculum, after subtracting completed requirements. Sources checked ${academic.checked}. Future offerings and registration eligibility remain unconfirmed.</p>`:''}
 ${!generated.courses.length?`<div class="empty"><h3>${academic.supported?'Your supported core requirements are complete or blocked for review.':'No verified institutional pathway is enabled for this selection.'}</h3><p>${academic.supported?'Check remaining electives, general education, minimum grades, and the official degree audit.':'Your completed classes are shown above. Add advisor-reviewed planned courses or select the supported UWB Electrical Engineering pathway.'}</p><a class="btn" href="#history">Review academic history →</a></div>`:`<div class="plan-terms">${Array.from({length:Math.max(terms,2)},(_,i)=>`<section class="plan-term" data-term="${i}"><div class="term-marker">${String(i+1).padStart(2,'0')}</div><div class="term-body"><div class="row"><h3>${termName(i)}</h3><span class="badge">${generated.courses.filter(c=>c.term===i).reduce((n,c)=>n+c.credits,0)} credits</span></div>${generated.courses.filter(c=>c.term===i).map(c=>`<article class="course" ${!academic.supported?`draggable="true" data-drag="${esc(c.code)}"`:''}><button class="btn course-move" data-move="${esc(c.code)}">Move to term ↗</button><strong>${esc(c.displayCode||c.code)} <span class="course-inline">${esc(c.title)}</span></strong><span>${c.credits} ${state.profile?.calendar==='Semester'?'semester':'quarter'} credits · ${esc(c.institution)}</span>${c.displayCode&&c.displayCode!==c.code?`<span>${c.institution===AcademicPathway.BC?'Fulfills the '+esc(c.code)+' course-content requirement under the published transfer guidance.':'Program requirement: '+esc(c.code)+'.'}</span>`:''}<details class="why-course"><summary>Why this quarter?</summary><p>${esc(c.explanation||'Placed using entered prerequisites and the selected credit cap.')}</p></details><span>${c.prereqs.length?'After '+esc(c.prereqs.join(', ')):'No earlier course in this roadmap'}${c.coreqs?.length?' · Co-requisites: '+esc(c.coreqs.join(', ')):''}</span>${academic.supported?`<label class="provider-label">Take this class at<select data-provider="${esc(c.code)}">${c.options.map(o=>`<option value="${esc(o.institution)}" ${o.institution===c.institution?'selected':''}>${esc(o.institution)} · ${esc(o.code)} · ${o.credits} credits</option>`).join('')}</select></label>${!c.options.some(o=>o.institution===AcademicPathway.BC)?`<span>No verified Bellevue substitution in this release. <a class="text-link" href="${AcademicPathway.sources.stem}" target="_blank" rel="noopener">Explore community-college equivalents ↗</a></span>`:''}${c.review?`<span>${esc(c.review)}</span>`:''}${c.series?'<span>Programming equivalency is for the full Bellevue CS 210/211 series. Mixed-school single-course combinations need advisor confirmation.</span>':''}${c.lab&&c.institution===AcademicPathway.UWB?`<span>Includes the required ${esc(c.lab)} skills lab (1 credit).</span>`:''}<span><a class="text-link" href="${c.source}" target="_blank" rel="noopener">Published requirement ↗</a> · Offering unconfirmed</span>`:'<span>Offering unconfirmed</span>'}</article>`).join('')||'<p class="muted">No core courses placed. Use this term for approved electives or verify the seasonal course sequence.</p>'}</div></section>`).join('')}</div>`}
 ${academic.supported?`<section class="card elective-picker"><span class="tag">EE ELECTIVES / 15 CREDITS</span><h3>Choose three electives to add to your roadmap.</h3><p>This is a supported subset of UWB’s approved list; you can review the full list with your advisor.</p>${AcademicPathway.electives.map(c=>`<label><input type="checkbox" data-elective="${c.code}" ${(state.selectedElectives||[]).includes(c.code)?'checked':''}> ${c.code} · ${c.title}</label>`).join('')}<a class="text-link" href="${AcademicPathway.sources.curriculum}" target="_blank" rel="noopener">Complete official elective list ↗</a></section>`:''}
 <div class="actions"><button class="btn" id="regenerate">Rebuild roadmap ↻</button><button class="btn primary" id="export-image">Download plan image ↓</button><button class="btn" id="export-plan">Plan data ↓</button></div><details class="plan-explanation"><summary>What is covered and what still needs review?</summary><p>UWB EE foundation, writing, and core requirements generate courses automatically. Completed credit is matched by published course mappings and transcript evidence. The plan respects listed prerequisites, co-requisites, workload caps, and published capstone seasons. It assumes you earn the required future grades; it is not a registration or admission guarantee.</p><p>General education, the 180-credit minimum, residency, skills-lab waivers, choice of electives, catalog-year exceptions, and source-college enrollment prerequisites still require an official degree audit. UWB permits at most 15 EE transfer credits without a petition. Bellevue options are enabled only where a published match is available; uncertain alternatives stay visibly unverified.</p></details>
 </div><aside class="plan-sidebar"><div class="card"><span class="tag">UWB EE ADMISSION</span><h3>One university. A separate major milestone.</h3><p>Current UWB students use the internal major application. Bellevue enrollment does not make you a new university transfer applicant.</p>${academic.admission?.map(a=>`<p>${a.record&&AcademicPathway.gradeValue(a.record)>=a.minimum?'✓':'○'} ${a.code}: minimum ${a.minimum.toFixed(1)}</p>`).join('')||''}<p>Also verify a 2.7 cumulative GPA, a 2.6 average across the three math/physics prerequisites, and the composition requirement. No acceptance is predicted.</p><a class="btn" href="${AcademicPathway.sources.admissions}" target="_blank" rel="noopener">Official major application guidance ↗</a></div><div class="card"><span class="tag">BOTH SCHOOLS, ONE RECORD</span><p>Community college remains an option while you attend UWB. Check cross-enrollment, financial aid, and course registration policies with both institutions.</p><a class="text-link" href="#history">Review combined classes ↗</a><a class="text-link" href="${AcademicPathway.sources.stem}" target="_blank" rel="noopener">UWB’s transfer equivalency table ↗</a></div><div class="card"><a href="#applications">Application checklist →</a><a href="#career">Career preparation →</a><a href="#scenarios">Compare a what-if →</a></div></aside></div>`,true);
}

function bindPlanFlow(){
 bindPlannerLab();
 document.querySelector('#prefer-community')?.addEventListener('change',e=>{state.profile||={};state.profile.preferCommunity=e.target.checked;state.courseProviders={};if(typeof recordPlanChange==='function')recordPlanChange('Global community-college preference changed; explicit school overrides were reset at your request.');else state.manual=null;save();render()});
 document.querySelectorAll('[data-provider]').forEach(el=>el.onchange=()=>{state.courseProviders||={};state.courseProviders[el.dataset.provider]=el.value;if(typeof recordPlanChange==='function')recordPlanChange('School changed for '+el.dataset.provider+' to '+el.value+'. Credits and sequencing recalculated.');else state.manual=null;const y=window.scrollY;save();render();window.scrollTo(0,y);toast('School updated for this class. Your roadmap has been recalculated.')});
 document.querySelectorAll('[data-elective]').forEach(el=>el.onchange=()=>{const selected=new Set(state.selectedElectives||[]);if(el.checked){if(selected.size>=3){el.checked=false;return toast('Choose three electives. Remove one to change your selection.')}selected.add(el.dataset.elective)}else selected.delete(el.dataset.elective);state.selectedElectives=[...selected];state.manual=null;const y=window.scrollY;save();render();window.scrollTo(0,y)});
document.querySelector('#history-next')?.addEventListener('click',()=>{state.historyDone=true;save()});document.querySelector('#skip-history')?.addEventListener('click',()=>{state.historyDone=true;save();location.hash='profile'});document.querySelector('#resolve-existing')?.addEventListener('click',()=>{const merged=E.consolidate(state.courses);state.courses=merged.courses;save();render();toast(`${merged.merged.length} duplicates combined.`)})}
async function deleteWorkspace(){
 if(!confirm('Delete all your Camino data? This permanently removes saved courses, plans, goals, quiz answers, application drafts and imported document data from this browser, plus your saved workspace if signed in. Downloaded files and information already sent to external services cannot be erased here. This cannot be undone.'))return;
 if(accountSaving)return toast('A save is in progress. Please try again in a moment.');
 clearTimeout(accountTimer);accountDirty=false;
 if(accountUser){try{const res=await accountFetch('/api/workspace',{method:'DELETE',headers:accountHeaders()});const data=await res.json();if(!res.ok)throw Error(data.error||'Deletion failed');accountGeneration++;accountEtag=null;accountCloud=null;}catch(e){toast('Could not delete your saved account workspace: '+e.message+'. Your data has not been cleared.');return}}
 try{for(const storage of [localStorage,sessionStorage])for(const key of Object.keys(storage))if(key.startsWith('camino-'))storage.removeItem(key);}catch(e){toast('Could not clear browser storage. Use your browser’s site-data settings to finish deletion.');return}
 if(typeof essayRequestController!=='undefined'){essayRequestController?.abort();essayRequestController=null;essayRequestTarget=null;}
 state={courses:[],tasks:{},scenarios:[]};window.currentPlan=[];answers=[];quizIndex=0;quizLength=12;mode='Balanced';importToken++;OCRRuntime.stop();schoolHeaderCache.clear();importDraft={files:[],rows:[],busy:false,message:''};globalThis.caminoRecoveryError=null;globalThis.caminoRecoveryRaw=null;
 if(typeof Forest3D!=='undefined')Forest3D.sync(null);
 for(const form of document.querySelectorAll('form'))form.reset();
 try{localStorage.setItem('camino-wipe-event',String(Date.now()));localStorage.removeItem('camino-wipe-event')}catch{}
 location.hash='privacy';render();toast('All Camino data on this browser and your saved workspace have been deleted.');setTimeout(()=>location.reload(),500);return true;
}

function bothellTransferRows(){const rows=AcademicPathway.groups.filter(g=>g.bc.length&&(!state.transferSearch||g.bc.some(c=>c.toUpperCase().includes(state.transferSearch.toUpperCase()))));return `<h2>Bellevue → UW Bothell published pathways</h2><p class="plan-scope">Current published guidance checked ${AcademicPathway.checked}. Catalog-year exceptions and enrollment prerequisites still need confirmation.</p><div class="table-wrap"><table><thead><tr><th>Bellevue course(s)</th><th>UWB requirement / credit</th><th>Evidence and limits</th></tr></thead><tbody>${rows.map(g=>`<tr><td>${g.bc.map(esc).join(' / ')}</td><td>${(g.uw.length?g.uw:g.transfer).map(esc).join(' / ')}</td><td><a class="text-link" href="${g.source}" target="_blank" rel="noopener">Official published source ↗</a><br>${g.id.startsWith('hist')?'Generic history credit; exact record matches require transcript evidence.':'Course-content guidance; degree applicability and grade minima remain separate.'}<br>Checked ${AcademicPathway.checked}</td></tr>`).join('')}</tbody></table></div><div class="note">The full Bellevue CS 210/211 series maps to UWB CSS/CSSSKL 142/143 under UWB’s STEM table. Single-course mixed-school programming sequences require advisor review. Chemistry series and Math III combinations also need individual review. There is no assumption that an elective bucket satisfies a named major prerequisite.</div><a class="btn" href="#roadmap">Back to your combined-school roadmap →</a>`}
